<html lang="th">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ทดสอบ RealSense · สถานี A</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#edf1f5;color:#182338;font:16px/1.6 system-ui,sans-serif}
main{width:min(100% - 32px,900px);margin:36px auto}section{background:#fff;border:1px solid #d9e2ea;border-radius:20px;padding:clamp(16px,4vw,28px);margin-bottom:16px}
h1,h2,p,dl{margin:0}h1{font-size:clamp(1.5rem,5vw,2rem)}h2{font-size:1.15rem;margin-bottom:10px}
.controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:14px 0}
button{border:0;border-radius:10px;padding:9px 15px;background:#174ea6;color:#fff;font:inherit;cursor:pointer}
button.secondary{background:#e8eef6;color:#163251}button:disabled{opacity:.45;cursor:default}
video{display:block;background:#132136;width:100%;aspect-ratio:16/9;object-fit:contain;border-radius:12px}
dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:4px 14px}dd{margin:0;overflow-wrap:anywhere}dt{font-weight:600}
#status{font-weight:650}#status[data-state=ok]{color:#11663e}#status[data-state=error]{color:#a12625}
small{display:block;color:#4b5d73;margin-top:10px}@media(max-width:480px){main{margin-top:16px}dl{grid-template-columns:1fr;gap:0}dd{margin-bottom:8px}}
</style></head><body><main>
<section><h1>ทดสอบกล้อง RealSense · สถานี A</h1><p id="status" role="status">ยังไม่ได้เปิดกล้อง</p>
<div class="controls"><button id="start">เริ่มทดสอบกล้อง RGB</button><button id="stop" class="secondary" disabled>หยุดกล้อง</button></div>
<video id="video" autoplay muted playsinline aria-label="ภาพสดจาก RealSense RGB"></video>
<small>เปิดหน้านี้บนคอมที่เสียบกล้อง USB ภาพแสดงในเบราว์เซอร์บนเครื่องนี้</small></section>
<section><h2>ข้อมูลอุปกรณ์และผลทดสอบ</h2><dl>
<dt>อุปกรณ์</dt><dd>Intel RealSense D435i</dd><dt>หมายเลขเครื่องล่าสุดที่ตรวจใน Windows</dt><dd><code>043323050394</code></dd>
<dt>USB VID / PID</dt><dd><code>8086:0B3A</code></dd>
<dt>พอร์ต USB ที่ตรวจพบ</dt><dd><code>Port_#0014.Hub_#0002</code></dd>
<dt>อินเทอร์เฟซ</dt><dd>RGB <code>MI_03</code> · Depth <code>MI_00</code> (หน้านี้ทดสอบ RGB)</dd>
<dt>ช่องทางภาพ</dt><dd>USB → Windows Camera → เบราว์เซอร์ · Node-RED เสิร์ฟหน้าเว็บที่ <code>1881</code></dd>
<dt>ภาพที่รับได้</dt><dd id="format">รอทดสอบ</dd>
<dt>ผลสดล่าสุดในเบราว์เซอร์</dt><dd id="last">ยังไม่มีผลที่บันทึก</dd>
<dt>ความสูงกล้อง</dt><dd>รอวัดที่สถานี A</dd>
</dl></section><section id="camera-test-records" aria-labelledby="record-title"><h2 id="record-title">ผลทดสอบแยกตามหมายเลขเครื่อง</h2><dl><dt>ตัวที่ 1 · 043323052370</dt><dd>ผ่าน RGB · 1280 × 720 · 30 fps · 26 พ.ย. 2569 16:16:20 น.</dd><dt>ตัวที่ 2 · 043323050394</dt><dd>ผ่าน RGB · 1280 × 720 · 30 fps · 26 พ.ย. 2569 16:22:32 น.</dd></dl><small>fps เป็นค่าที่สตรีมรายงาน ทั้งสองตัวใช้ USB Port_#0014.Hub_#0002 ทีละตัว ผลสดด้านบนใช้กล้อง RealSense RGB ที่เชื่อมต่อ ส่วนหมายเลขเครื่องในบันทึกยืนยันจาก Windows ขณะทดสอบ</small></section></main>
<script>
const video = document.getElementById('video');
const status = document.getElementById('status');
const start = document.getElementById('start');
const stop = document.getElementById('stop');
const format = document.getElementById('format');
const last = document.getElementById('last');
const storageKey = 'station-a-realsense-rgb-last-live-result';
let stream;
let timer;
let frameWatch;
let generation = 0;

function setStatus(text, state = '') {
  status.textContent = text;
  status.dataset.state = state;
}

function releaseTracks() {
  ++generation;
  clearTimeout(timer);
  clearInterval(frameWatch);
  if (stream) stream.getTracks().forEach(track => track.stop());
  stream = null;
  video.srcObject = null;
  start.disabled = false;
  stop.disabled = true;
}

function showLast(result) {
  last.textContent = new Date(result.at).toLocaleString('th-TH') + ' · ' + result.format;
}
try {
  const saved = JSON.parse(localStorage.getItem(storageKey));
  if (saved && saved.at && saved.format) showLast(saved);
} catch {}

function realSenseRgb(devices) {
  return devices.find(device => device.kind === 'videoinput'
    && /realsense|d435i/i.test(device.label) && /rgb|color/i.test(device.label));
}

start.addEventListener('click', async () => {
  const run = ++generation;
  start.disabled = true;
  setStatus('กำลังเปิดกล้อง RealSense RGB…');
  format.textContent = 'รอภาพจริง';
  try {
    if (!navigator.mediaDevices?.getUserMedia) throw new Error('เปิดผ่าน http://127.0.0.1:1881 บนคอมที่เสียบกล้อง');
    let camera = realSenseRgb(await navigator.mediaDevices.enumerateDevices());
    if (!camera) {
      const permissionStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      try {
        camera = realSenseRgb(await navigator.mediaDevices.enumerateDevices());
      } finally {
        permissionStream.getTracks().forEach(track => track.stop());
      }
    }
    if (!camera) throw new Error('เบราว์เซอร์ไม่พบ RealSense RGB');
    stream = await navigator.mediaDevices.getUserMedia({
      video: { deviceId: { exact: camera.deviceId }, width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 30 } },
      audio: false,
    });
    const track = stream.getVideoTracks()[0];
    if (!/realsense|d435i/i.test(track.label) || !/rgb|color/i.test(track.label)) throw new Error('อุปกรณ์ที่เปิดไม่ใช่ RealSense RGB');
    track.addEventListener('ended', () => {
      if (run !== generation) return;
      releaseTracks();
      setStatus('กล้องหยุดส่งภาพหรือหลุดการเชื่อมต่อ', 'error');
    });
    video.srcObject = stream;
    stop.disabled = false;
    await video.play();
    if (run !== generation) return;

    const initialTime = video.currentTime;
    frameWatch = setInterval(() => {
      if (run !== generation || !video.videoWidth || video.currentTime <= initialTime + 0.1) return;
      clearInterval(frameWatch);
      clearTimeout(timer);
      const fps = track.getSettings().frameRate;
      const detail = video.videoWidth + ' × ' + video.videoHeight + (fps ? ' · ' + Math.round(fps * 10) / 10 + ' fps (ค่าของสตรีม)' : '');
      format.textContent = detail;
      setStatus('ผ่าน · ได้รับภาพสดจาก RealSense RGB', 'ok');
      const result = { at: new Date().toISOString(), format: detail };
      showLast(result);
      try { localStorage.setItem(storageKey, JSON.stringify(result)); } catch {}
    }, 150);
    timer = setTimeout(() => {
      if (run !== generation) return;
      releaseTracks();
      setStatus('เปิดกล้องแล้วแต่ยังไม่ได้รับภาพ', 'error');
    }, 10000);
  } catch (error) {
    if (run !== generation) return;
    releaseTracks();
    const detail = {
      NotAllowedError: 'ยังไม่ได้อนุญาตให้เบราว์เซอร์ใช้กล้อง',
      NotReadableError: 'เปิดกล้องไม่ได้ ลองปิดโปรแกรมอื่นที่กำลังใช้กล้อง',
      NotFoundError: 'เบราว์เซอร์ไม่พบกล้อง',
    }[error.name] || error.message;
    setStatus(detail, 'error');
  }
});
stop.addEventListener('click', () => {
  releaseTracks();
  setStatus('หยุดกล้องแล้ว');
});
window.addEventListener('pagehide', releaseTracks);
</script></body></html>"; return msg;
